        table: { headers: ['Situación', 'Conclusión probable de control', 'Por qué'], rows: [['55 % de derechos de voto, sin restricciones', 'Control — consolidar', 'Poder + rendimientos variables + vínculo todos presentes'], ['42 %, otros dispersos, siempre gana las votaciones', 'Control de hecho — consolidar', 'Poder en la práctica a pesar de <50 %'], ['Opción actualmente ejercitable que lleva la participación al 60 %', 'Control — consolidar', 'Los derechos de voto potenciales sustantivos dan poder'], ['Gestor de fondos, los inversores pueden destituirlo a voluntad', 'Sin control — agente', 'Actúa para otros; los derechos de destitución indican agencia'], ['Patrocinador de un vehículo de titulización, gestiona activos, posee el tramo de patrimonio', 'Control — consolidar', 'Poder contractual + rendimientos variables en una entidad estructurada']] }
